const t={ui:{fig:"Abb. 1",title:"Futter einnähen",svgLabel:"Eine isometrische Zeichnung, wie man Futter in eine Tasche einnäht: das Futter mit Wendeöffnung, das Außenteil darin, die Naht an der Oberkante, das Wenden durch die Öffnung, das Schließen der Öffnung und das Absteppen.",prev:"Vorheriger Schritt",dot:(e,n)=>e?`Schritt ${e}: ${n}`:n,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,n)=>`Schritt ${e} von ${n}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Zerlegen",putTogether:"Zusammensetzen",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT"},stitches:{straight:"Geradstich"},labels:{liningInsideOut:"Futter auf links",opening8:"Wendeöffnung 8 cm",outerRightOut:"Außenteil auf rechts",cm6:"6 cm",strapsBetween:"Henkel dazwischen",rightSides:"rechts auf rechts",seam05:"Naht 0,5 cm",turnThrough:"durch die Öffnung wenden",rightSideOut:"auf rechts gewendet",tuckEdges:"Kanten nach innen",stitchEdge:"knappkantig zunähen",pushLining:"Futter hineinschieben",pressEdge:"Oberkante bügeln",topstitch1:"1 cm absteppen"},steps:[{title:"Die gefütterte Tasche",text:"Außenteil und Futter werden an der Oberkante zusammengenäht, durch eine Öffnung im Futter gewendet und abgesteppt. Tippe auf die Tasche, um sie zu zerlegen."},{title:"Futter mit Wendeöffnung nähen",text:"Nähe das Futter wie das Außenteil und lass es auf links – aber mit einer 8 cm langen Wendeöffnung unten in einer Seitennaht. Durch sie wendest du später die Tasche.",details:["Nähe das Futter genauso wie das Außenteil und lass es auf links.","Lass in einer Seitennaht eine Öffnung: bei der Tote Bag ist sie 8 cm lang, weit unten, direkt über dem Boden.","Die Öffnung darf beliebig lang sein, solange die Tasche hindurchpasst. Ein steifes Teil braucht mehr Platz: Das Utensilo hat Wände mit Bügeleinlage und eine 15 cm lange Öffnung in einer Ecknaht."]},{title:"Außenteil ins Futter stecken",text:"Wende das Außenteil auf rechts und schieb es in das auf links gedrehte Futter, rechts auf rechts. Die Henkel liegen dazwischen, 6 cm von der Mitte entfernt festgesteckt.",details:["Wende das Außenteil auf rechts; das Futter bleibt auf links.","Bei der Tote Bag steckst du vorher die Henkel an die Oberkante des Außenteils: die Enden bündig mit der Kante, 6 cm von der Mitte entfernt, die Schlaufen hängen nach unten über die Tasche.","Schieb das Außenteil so in das Futter, dass die rechten Seiten aufeinanderliegen und die Henkel dazwischen. Leg die Seitennähte und die Oberkanten aufeinander und fixiere sie mit Klammern."]},{title:"Oberkante zusammennähen",text:"Nähe einmal rundherum an der Oberkante entlang, 0,5 cm von der Kante entfernt – durch Futter, Henkel und Außenteil.",details:["Nähe rundherum an der Oberkante entlang, 0,5 cm von der Kante entfernt, durch alle Lagen: Futter, Henkel und Außenteil.","Bei der Tote Bag und beim Utensilo ist diese Naht gleich: 0,5 cm."]},{title:"Durch die Wendeöffnung wenden",text:"Greif durch die Öffnung im Futter und zieh die ganze Tasche hindurch. Das Außenteil kommt auf rechts heraus, das Futter ragt oben darüber hinaus.",details:["Greif durch die Öffnung im Futter, fass das Außenteil und zieh die ganze Tasche hindurch.","Streich das Außenteil glatt – es ist jetzt auf rechts. Das Futter ist ebenfalls auf rechts und ragt oben aus der Tasche heraus, seine Öffnung ist noch offen."]},{title:"Wendeöffnung schließen",text:"Schlag die Kanten der Öffnung entlang der Nahtlinie nach innen ein und nähe sie mit der Nähmaschine knappkantig zu. Oder schließ sie von Hand mit dem Matratzenstich.",details:["Schlag die offenen Kanten der Öffnung nach innen ein, in einer Linie mit der übrigen Naht, sodass die beiden Bruchkanten aufeinandertreffen.","Die erste Möglichkeit, mit der Nähmaschine: Steppe die beiden Bruchkanten knappkantig zusammen. So sind die Tote Bag und das Utensilo geschlossen; die Naht verschwindet danach in der Tasche.","Die zweite Möglichkeit, von Hand mit dem Matratzenstich (Leiterstich): Bügle die beiden Bruchkanten, fädle Garn in der Farbe des Stoffs ein und versteck den Knoten in einer Bruchkante.","Nähe einen kleinen Stich in der einen Bruchkante, dann genau gegenüber einen kleinen Stich in der anderen. Mach immer abwechselnd so weiter, von einer Seite zur anderen: Die Fäden zwischen den Kanten sehen aus wie die Sprossen einer Leiter.","Zieh alle paar Stiche den Faden an – die Kanten schließen sich und die Stiche verschwinden. Zum Schluss vernähst du den Faden und versteckst das Ende im Futter."]},{title:"Futter hineinschieben",text:"Schieb das Futter in die Tasche hinein und bügle die Oberkante flach.",details:["Schieb das Futter nach unten in das Außenteil, bis ganz auf den Boden.","Bei der Tote Bag bügelst du die Oberkante flach. Beim Utensilo streichst du das Futter in den Ecken glatt."]},{title:"Oberkante absteppen",text:"Steppe die Oberkante rundherum 1 cm von der Kante entfernt ab. Beim Utensilo sind es 0,5 cm.",details:["Steppe rundherum an der Oberkante ab, durch Außenteil und Futter: bei der Tote Bag 1 cm von der Kante entfernt, beim Utensilo 0,5 cm.","Deine Tasche ist fertig!"]}],legend:[{title:"Außenteil",text:"auf rechts · bei der Tote Bag sind die Henkel 6 cm von der Mitte in die Oberkante eingenäht"},{title:"Futter",text:"wie das Außenteil genäht, auf links gelassen, dann gewendet und hineingeschoben"},{title:"Wendeöffnung",text:"in einer Naht des Futters: 8 cm in einer Seitennaht der Tote Bag, 15 cm in einer Ecknaht des Utensilos · knappkantig zugenäht"},{title:"Naht an der Oberkante",text:"Außenteil und Futter rechts auf rechts, 0,5 cm von der Kante"},{title:"Steppnaht",text:"1 cm von der Oberkante bei der Tote Bag, 0,5 cm beim Utensilo"}]};export{t as default};
